149: // findConflict finds the index of the conflict.
150: // It returns the first pair of conflicting entries between the existing
151: // entries and the given entries, if there are any.
152: // If there is no conflicting entries, and the existing entries contains
153: // all the given entries, zero will be returned.
154: // If there is no conflicting entries, but the given entries contains new
155: // entries, the index of the first new entry will be returned.
156: // An entry is considered to be conflicting if it has the same index but
157: // a different term.
158: // The index of the given entries MUST be continuously increasing.
159: func (l *raftLog) findConflict(ents []pb.Entry) uint64 {
160: 	for i := range ents {
161: 		if id := pbEntryID(&ents[i]); !l.matchTerm(id) {
162: 			if id.index <= l.lastIndex() {
163: 				// TODO(pav-kv): can simply print %+v of the id. This will change the
164: 				// log format though.
165: 				l.logger.Infof("found conflict at index %d [existing term: %d, conflicting term: %d]",
166: 					id.index, l.zeroTermOnOutOfBounds(l.term(id.index)), id.term)
167: 			}
168: 			return id.index
169: 		}
170: 	}
171: 	return 0
172: }
